G1=$(group 'fwshift-addresses' 'FWShift: for the interfaces of 0.0.0.0-10.0.255.255 10.2.0.0-172.16.29.255 172.16.31.0-192.168.9.255 192.168.11.0-198.51.100.0 198.51.100.2-255.255.255.255') || exit 1
